import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { IndexCard, IndexCardContent, IndexCardFooter, IndexCardHeader, IndexCardTitle } from "@/components/ui/index-card";
import { Mascot } from "@/components/ui/mascot";
import { Polaroid, PolaroidCaption, PolaroidImage } from "@/components/ui/polaroid";
import { Sticker } from "@/components/ui/sticker";
import { StickyNote, StickyNoteContent, StickyNoteTitle } from "@/components/ui/sticky-note";
const LandingHero01Collage = defineUi<{}>("LandingHero01Collage", [], (_props, {
  slots: _slots
}) => {
  return () => {
    return <div data-slot="landing-hero-collage" class="mx-auto flex max-w-full flex-wrap items-start justify-center gap-x-8 gap-y-8 pt-2 @xl:relative @xl:block @xl:h-[30rem] @xl:w-[26rem] @xl:pt-0">
      <Polaroid seed="hero-photo" tape="top" tapeKind="washi-dots" class="w-60 max-w-full @xl:absolute @xl:start-0 @xl:top-2">
        <PolaroidImage scene="hills" label="A drawn hillside with one tree and a sun" seed="hero-hills" />
        <PolaroidCaption>monday, 9:41</PolaroidCaption>
      </Polaroid>

      <StickyNote color="yellow" fastener="pin" seed="hero-todo" class="w-44 @xl:absolute @xl:start-[13.5rem] @xl:top-20">
        <StickyNoteTitle>todo</StickyNoteTitle>
        <StickyNoteContent>ship the new page (friday!)</StickyNoteContent>
      </StickyNote>

      <IndexCard seed="hero-roadmap" fastener="clip" class="min-h-0 w-60 max-w-full @xl:absolute @xl:start-10 @xl:top-[18rem]">
        <IndexCardHeader>
          <IndexCardTitle>Roadmap</IndexCardTitle>
        </IndexCardHeader>
        <IndexCardContent>
          <p>1. draw the thing</p>
          <p>2. show a friend</p>
          <p>3. ship it</p>
        </IndexCardContent>
        <IndexCardFooter>
          <span class="ll-num">no. 0042</span>
        </IndexCardFooter>
      </IndexCard>

      <Mascot pose="wave" size={184} class="h-[184px] w-auto @xl:absolute @xl:end-0 @xl:bottom-0" />
      <Sticker name="rocket" size={76} rotate={10} class="hidden @xl:absolute @xl:-top-2 @xl:end-2 @xl:block" />
    </div>;
  };
});
export { LandingHero01Collage };

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { Button } from "@/components/ui/button";
import { Mascot } from "@/components/ui/mascot";
const links = ["Product", "Pricing", "Notes", "Changelog"];
const LandingHero01Nav = defineUi<{}>("LandingHero01Nav", [], (_props, {
  slots: _slots
}) => {
  return () => {
    return <header class="flex items-center justify-between gap-4 pt-6">
      <a href="#top" class="flex items-center gap-2 font-script text-3xl leading-none font-bold text-ink">
        <Mascot pose="idle" size={32} />
        penmark
      </a>
      <nav aria-label="Main" class="hidden items-center gap-3 text-base text-ink @2xl:flex">
        {links.map(l => <a key={l} href={`#${l.toLowerCase()}`} class="px-3 py-1 hover:ll-swipe">
            {l}
          </a>)}
      </nav>
      <div class="flex items-center gap-3">
        <Button asChild variant="ghost" size="sm" class="hidden @md:inline-flex">
          <a href="#sign-in">Sign in</a>
        </Button>
        <Button asChild size="sm">
          <a href="#start">Get started</a>
        </Button>
      </div>
    </header>;
  };
});
export { LandingHero01Nav };

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, useId } from "vue";
import { Avatar, AvatarFallback, AvatarGroup, AvatarGroupCount } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import { Annotate } from "@/components/ui/annotate";
import { Icon } from "@/components/ui/icon";
import { Lettering } from "@/components/ui/lettering";
import { Paper } from "@/components/ui/paper";
import { Rating } from "@/components/ui/rating";
import { LandingHero01Collage } from "@/blocks/landing-hero-01/components/landing-hero-01-collage";
import { LandingHero01Nav } from "@/blocks/landing-hero-01/components/landing-hero-01-nav";
const people = ["Ada Lovelace", "Jo Okafor", "Mika Kobayashi", "Sam Reyes"];
const LandingHero01 = defineUi<{}>("LandingHero01", [], (_props, {
  slots: _slots
}) => {
  const titleId = useId();
  return () => {
    return <div class="@container relative w-full overflow-x-clip">
      <div class="p-8">
        <Paper as="section" aria-labelledby={titleId} stock="paper" tilt={false} tape="both" tapeKind="washi-dots" seed="landing-hero-01" class="mx-auto w-full max-w-6xl px-5 pb-14 @xl:px-10 @xl:pb-16">
          <LandingHero01Nav />

          <div class="mt-10 grid items-center gap-12 @5xl:mt-14 @5xl:grid-cols-[minmax(0,1fr)_26rem] @5xl:gap-12">
            <div class="min-w-0">
              <p class="font-type text-sm text-pencil-text">Notes and tasks for small teams</p>
              <Lettering as="h1" id={titleId} size="xl" tone="marker" wobble={0.5} seed="hero-title" class="mt-3">
                Write it down.
              </Lettering>
              <p class="mt-5 max-w-xl text-xl/8 text-balance text-ink-soft @xl:text-[22px]/9">
                Penmark keeps your team&rsquo;s notes, tasks and half-formed ideas on{" "}
                <Annotate type="underline" kind="wavy" color="blue" animate delay={600} seed="hero-underline">
                  one calm page
                </Annotate>
                , so the good stuff gets{" "}
                <Annotate type="highlight" color="yellow" animate delay={1100} seed="hero-highlight">
                  found
                </Annotate>
                , not lost.
              </p>

              <div class="mt-8 flex flex-wrap items-center gap-x-4 gap-y-3">
                <Button asChild size="lg">
                  <a href="#start">
                    Start a notebook
                    <Icon name="arrow-right" class="rtl:-scale-x-100" />
                  </a>
                </Button>
                <Button asChild size="lg" variant="outline">
                  <a href="#tour">
                    <Icon name="circle-play" />
                    Watch the tour
                  </a>
                </Button>
              </div>
              <p class="mt-4 text-[15px] text-ink-muted">
                <Annotate type="circle" color="red" animate delay={1600} seed="hero-free" class="mx-1">
                  Free
                </Annotate>{" "}
                for teams of five. No card, no catch.
              </p>

              <div class="mt-10 flex flex-wrap items-center gap-x-5 gap-y-3">
                <AvatarGroup class="[--ll-avatar-group-ring:var(--ll-paper)] [&>*+*]:-ms-0.5">
                  {people.map(name => <Avatar key={name}>
                      <AvatarFallback name={name} />
                    </Avatar>)}
                  <AvatarGroupCount>+4k</AvatarGroupCount>
                </AvatarGroup>
                <div>
                  <Rating readOnly value={4.5} allowHalf size="sm" aria-label="Rated 4.5 out of 5 by our customers" />
                  <p class="text-sm text-ink-muted">Loved by 4,200 small teams</p>
                </div>
              </div>
            </div>

            <LandingHero01Collage />
          </div>
        </Paper>
      </div>
    </div>;
  };
});
export default LandingHero01;
